  --focus-ring:     #818cf8;
  --shadow-lg:      0 24px 60px rgba(0, 0, 0, 0.7);
  --radius-sm:      6px;
  --radius-md:      10px;
  --radius-lg:      16px;
  --transition:     150ms ease;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  line-height: 1.5;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  outline-offset: 2px;
}
.skip-link:focus { top: 1rem; }

/* ── Page layout ── */
.page-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1.25rem 2rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-card);
}
.page-header h1 {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
}
.header-icon {
  width: 28px;
  height: 28px;
  color: var(--accent);
  flex-shrink: 0;
}

main {
  padding: 2.5rem 2rem;
  max-width: 900px;
  margin: 0 auto;
}

/* ── Breadcrumb ── */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
  list-style: none;
}
.breadcrumb a {
  color: var(--text-secondary);
  text-decoration: none;
}
.breadcrumb a:hover { color: var(--text-primary); }
.breadcrumb a:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
  border-radius: 2px;
}
.breadcrumb-sep { color: var(--text-muted); }
.breadcrumb [aria-current="page"] { color: var(--text-primary); }

/* ── Image card ── */
.image-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.image-preview {
  position: relative;
  background: #11131c;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 320px;
  overflow: hidden;
}

.preview-img {
  width: 100%;
  max-height: 420px;
  object-fit: cover;
  display: block;
}

/* Placeholder when no real image */
.img-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  padding: 3rem;
  color: var(--text-muted);
  font-size: 0.9rem;
  width: 100%;
  min-height: 320px;
  justify-content: center;
  background:
    radial-gradient(ellipse 60% 40% at 50% 50%, #1c2040 0%, transparent 70%),
    repeating-linear-gradient(
      45deg,
      #13161f 0px,
      #13161f 10px,
      #141720 10px,
      #141720 20px
    );
}
.img-placeholder svg { opacity: 0.3; }
.img-placeholder span { opacity: 0.5; }

/* ── Image meta / toolbar ── */
.image-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--border);
}

.image-info { flex: 1; min-width: 0; }
.image-filename {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.image-meta {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-top: 0.2rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.image-meta span { display: flex; align-items: center; gap: 0.3rem; }

/* ── Action buttons ── */
.image-actions {
  display: flex;
  gap: 0.625rem;
  align-items: center;
  flex-shrink: 0;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  white-space: nowrap;
  line-height: 1.25;
}
.btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}
.btn svg { flex-shrink: 0; }

.btn-ghost {
  background: transparent;
  border-color: var(--border-strong);
  color: var(--text-secondary);
}
.btn-ghost:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-strong);
  color: var(--text-primary);
}

.btn-danger {
  background: var(--danger-bg);
  border-color: var(--danger-border);
  color: var(--danger);
}
.btn-danger:hover {
  background: rgba(239, 68, 68, 0.2);
  border-color: rgba(239, 68, 68, 0.6);
  color: var(--danger-hover);
}

/* Confirm delete (dialog) */
.btn-danger-solid {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
  font-weight: 600;
}
.btn-danger-solid:hover {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}

.btn-cancel {
  background: transparent;
  border-color: var(--border-strong);
  color: var(--text-secondary);
}
.btn-cancel:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-strong);
  color: var(--text-primary);
}

/* ── Modal backdrop ── */
dialog::backdrop {
  background: rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(4px);
}

/* ── Dialog ── */
dialog {
  background: var(--bg-dialog);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  color: var(--text-primary);
  padding: 0;
  width: min(460px, calc(100vw - 2rem));
  max-width: 100%;
  /* override browser default positioning */
  position: fixed;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  margin: 0;
}

/* animation */
@media (prefers-reduced-motion: no-preference) {
  dialog[open] {
    animation: dialog-in 200ms ease forwards;
  }
  @keyframes dialog-in {
    from { opacity: 0; scale: 0.95; }
    to   { opacity: 1; scale: 1; }
  }
}

.dialog-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1.4rem 1.5rem 0;
}
.dialog-icon-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--danger-bg);
  border: 1px solid var(--danger-border);
  flex-shrink: 0;
  color: var(--danger);
}
.dialog-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
}

.dialog-body {
  padding: 1rem 1.5rem 0;
}
.dialog-description {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.65;
}
.dialog-filename-highlight {
  color: var(--text-primary);
  font-weight: 600;
}

.dialog-warning {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  margin-top: 1rem;
  padding: 0.75rem 1rem;
  background: rgba(239, 68, 68, 0.07);
  border: 1px solid var(--danger-border);
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  color: var(--danger-hover);
}
.dialog-warning svg { flex-shrink: 0; margin-top: 1px; }

.dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.625rem;
  padding: 1.25rem 1.5rem 1.5rem;
}

/* ── Live region ── */
#status-msg {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* ── Reflow ── */
@media (max-width: 480px) {
  main { padding: 1.5rem 1rem; }
  .image-toolbar { flex-direction: column; }
  .image-actions { width: 100%; }
  .btn { flex: 1; justify-content: center; }
  .dialog-footer { flex-direction: column-reverse; }
  .dialog-footer .btn { width: 100%; justify-content: center; }
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .btn { border: 1px solid ButtonBorder; }
  dialog { border: 1px solid CanvasText; }
  .dialog-icon-wrap { border: 1px solid ButtonBorder; }
  .dialog-warning { border: 1px solid ButtonBorder; }
}
