// ── Dialog controller ─────────────────────────────────────────────────────────
function initDialog() {
  const trigger  = document.getElementById('delete-trigger');
  const dialog   = document.getElementById('delete-dialog');
  const cancelBtn = document.getElementById('dialog-cancel');
  const confirmBtn = document.getElementById('dialog-confirm');
  const statusMsg  = document.getElementById('status-msg');

  // Focusable elements inside the dialog for focus-trap
  function getFocusable() {
    return Array.from(
      dialog.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      )
    ).filter(el => !el.disabled && el.offsetParent !== null);
  }

  function openDialog() {
    dialog.showModal();
    // Move focus to the cancel (safe) button — not the destructive one
    cancelBtn.focus();
  }

  function closeDialog(restoreFocus = true) {
    dialog.close();
    if (restoreFocus) trigger.focus();
  }

  // Open on trigger click
  trigger.addEventListener('click', openDialog);

  // Cancel: close and restore focus
  cancelBtn.addEventListener('click', () => closeDialog(true));

  // Confirm: perform deletion feedback, then close
  confirmBtn.addEventListener('click', () => {
    statusMsg.textContent = 'Image deleted from your library.';
    closeDialog(true);
    // Visual feedback on trigger (disabled state)
    trigger.disabled = true;
    trigger.textContent = 'Deleted';
    trigger.setAttribute('aria-label', 'Image has been deleted');
  });

  // Escape key is handled natively by <dialog>, but we still want
  // to restore focus when it fires (the 'cancel' event fires on Escape)
  dialog.addEventListener('cancel', (e) => {
    e.preventDefault(); // prevent default close so we control focus
    closeDialog(true);
  });

  // Focus trap — keep Tab cycling within the dialog
  dialog.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;
    const focusable = getFocusable();
    if (focusable.length === 0) return;
    const first = focusable[0];
    const last  = focusable[focusable.length - 1];

    if (e.shiftKey) {
      if (document.activeElement === first) {
        e.preventDefault();
        last.focus();
      }
    } else {
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  });
}

// ── Boot ──────────────────────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', App);
